const trips=[{place:'桂林',theme:'自然慢游',title:'山水桂林 · 漓江慢时光',days:5,route:'桂林 → 漓江 → 阳朔',image:'https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=900&q=85',plan:['抵达桂林，轻松适应旅行节奏','探索桂林山水与城市风貌','沿漓江走进山水画卷','阳朔田园漫步，自由探索','整理旅途记忆，返程']},{place:'云南',theme:'自然慢游',title:'自在云南 · 风与古城',days:7,route:'昆明 → 大理 → 丽江',image:'https://images.unsplash.com/photo-1513415564515-763d91423bdd?auto=format&fit=crop&w=900&q=85',plan:['抵达昆明，自由休息','昆明城市探索，前往大理','洱海周边慢游','大理古城与当地生活','前往丽江，古城漫步','自然风光探索，按兴趣调整','从丽江返程']},{place:'北京',theme:'人文探索',title:'漫游北京 · 寻迹古都',days:5,route:'北京 → 长城 → 北京',image:'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?auto=format&fit=crop&w=900&q=85',plan:['抵达北京，休息与街区漫步','古都文化探索，景点需提前预约','长城一日体验','胡同漫步与城市生活','自由安排，返程']}];
let current=0;const $=s=>document.querySelector(s);function render(place='all',theme='all'){const visible=trips.map((t,i)=>({...t,i})).filter(t=>(place==='all'||t.place===place)&&(theme==='all'||t.theme===theme));$('#trips').innerHTML=visible.map(t=>`<article class="trip"><img class="trip-image" src="${t.image}" alt="${t.place}旅行配图" loading="lazy"><div class="trip-body"><span class="trip-meta">${t.days} 天 · ${t.theme} · 示例</span><h3>${t.title}</h3><p>${t.route}</p><div class="trip-bottom"><span>行程可按需求调整</span><button data-trip="${t.i}">查看行程 ↗</button></div></div></article>`).join('');$('#empty').hidden=visible.length>0;}render();document.addEventListener('click',e=>{const b=e.target.closest('[data-trip]');if(b){current=Number(b.dataset.trip);const t=trips[current];$('#detail-title').textContent=t.title;$('#detail-desc').textContent=`${t.days}天 · ${t.route}`;$('#itinerary').innerHTML=t.plan.map((p,i)=>`<li>第 ${i+1} 天：${p}</li>`).join('');$('#detail').showModal();}});$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#custom-trip').onclick=()=>{$('#form').elements.place.value=trips[current].place;$('#form').elements.days.value=trips[current].days;$('#detail').close();location.hash='tailor';};function active(theme){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===theme));}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{$('#theme').value=b.dataset.filter;active(b.dataset.filter);render($('#destination').value,b.dataset.filter);});$('#find').onclick=()=>{render($('#destination').value,$('#theme').value);active($('#theme').value);location.hash='journeys';};document.querySelectorAll('[data-place]').forEach(a=>a.onclick=()=>{$('#destination').value=a.dataset.place;$('#theme').value='all';active('all');render(a.dataset.place);});$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');});$('#form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);$('#summary').textContent=`目的地：${d.get('place')}\n出行时间：${d.get('date')}\n同行人数：${d.get('people')} 人\n预计天数：${d.get('days')} 天\n旅行期待：${d.get('wish')||'待沟通'}\n\n此摘要尚未发送，请在客服渠道开通后联系确认。`;$('#result').hidden=false;$('#result').scrollIntoView({behavior:'smooth',block:'nearest'});};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#summary').textContent);$('#copy').textContent='已复制';}catch{$('#copy').textContent='请选中上方摘要手动复制';}};$('#year').textContent=new Date().getFullYear();
